css:
@font-face {
  font-family: 'CompanyFont';
  src: url('/files/company-font.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
}

.page {
  font-family: 'CompanyFont', Arial, sans-serif;
}





@page {
  size: A4;
  margin: 12mm;
}

.page {
  page-break-after: always;
  break-after: page;
}

.page:last-child {
  page-break-after: auto;
  break-after: auto;
}



.header {
  margin-top: 10px;
  margin-bottom: 10px;
}

.footer {
  margin-top: 10px;
}

.header img,
.footer img {
  width: 100%;
  height: auto;
  display: block;
}

.center {
  text-align: center;
  font-weight: bold;
}

.right {
  text-align: right;
  font-weight: bold;
}

.amount {
  text-align: center;
  white-space: nowrap;
}

.title-ar {
  font-weight: bold;
  font-size: 16px;
  margin-top: 4px;
}

.title-en {
  font-weight: bold;
  font-size: 18px;
  margin-bottom: 6px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border: 1px solid #2b66c7;
  padding: 5px 7px;
  vertical-align: middle;
  font-size: 10.5px;
  text-align: center;
  font-weight: bold;
}

.head-row th {
  background: #0e2a57;
  color: #fff;
  font-weight: 700;
  font-size: 12px;
  text-align: center;
}

.muted {
  color: #6b7280;
}

.net-bar td  {
  background: #0e2a57;
  color: #fff;
  font-weight: bold;
  text-align: center;
  font-size: 13px;
}

.approvals td {
  height: 26px;
}

.stamp-wrap {
  display: flex;
  justify-content: flex-end;
  margin-top: 10px;
}

.stamp-wrap img {
  width: 120px;
}

.iban {
  margin-top: 10px;
  font-size: 13px;
}

.money-line {
  direction: rtl;
  unicode-bidi: embed;

}

.money-line .amount {
  direction: ltr;
  unicode-bidi: isolate;
  margin-left: 6px;
    color:white;

}

.money-line .currency {
  margin-left: 6px;
    color:white;

}

.money-line .only {
  margin-right: 6px;
  font-weight: 600;
  color:white;
}
.empty-line {
  color: #999;
  letter-spacing: 2px;
  font-weight: bold;
}
